installation.script:
#!/bin/bash
# A small example, so the site answers before the real one is sent.
cd /mnt/server
if [ ! -f server.js ] && [ ! -f package.json ]; then
cat > server.js <<'APP'
const http = require('http');

http.createServer((request, response) => {
    response.writeHead(200, { 'Content-Type': 'text/html; charset=utf-8' });
    response.end('<h1>Your Node.js site is ready</h1><p>Replace server.js with your application. It must listen on process.env.PORT.</p>');
}).listen(process.env.PORT, '0.0.0.0', () => console.log('Listening on port ' + process.env.PORT));
APP
fi
echo "Done."
